def get_naive_rag_instruction(question, documents):
    return f"You are a knowledgeable assistant that uses the provided documents to answer the user's question.\n\nQuestion:\n{question}\nDocuments:\n{documents}\n"

def get_task_instruction_openqa(question, model_name=None):
    if model_name == 'qwq':
        user_prompt = f'Please answer the following question. You should provide your final answer in the format \\boxed{{YOUR_ANSWER}}.\n\nQuestion:\n{question}\n\n'
    elif model_name == 'dpsk':
        user_prompt = f'Please answer the following question.\n\nProvide your final answer in the format **ANSWER: {{YOUR_ANSWER}}**.\n\nQuestion:\n{question}\n\n'
    else:
        user_prompt = f'Please answer the following question. You should think step by step to solve it.\n\nProvide your final answer in the format \\boxed{{YOUR_ANSWER}}.\n\nQuestion:\n{question}\n\n'
    return user_prompt

