def get_task_instruction_multi_choice(question, model_name=None):
    if model_name == 'qwq':
        user_prompt = f'Please answer the following multiple-choice question. You should provide your final choice in the format \\boxed{{YOUR_CHOICE}}.\n\nQuestion:\n{question}\n\n'
    elif model_name == 'dpsk':
        user_prompt = f'Please answer the following multiple-choice question.\n\nProvide your final choice in the format **ANSWER: {{YOUR_CHOICE}}**.\n\nQuestion:\n{question}\n\n'
    elif model_name == 'llama':
        user_prompt = f'Please answer the following multiple-choice question. You should think step by step to solve it.\n\nProvide your final choice in the format \\boxed{{YOUR_CHOICE}}. Your final choice should be one of the letters A, B, C, or D, DO NOT include any answer content.\n\nQuestion:\n{question}\n\n'
    else:
        user_prompt = f'Please answer the following multiple-choice question. You should think step by step to solve it.\n\nProvide your final choice in the format \\boxed{{YOUR_CHOICE}}.\n\nQuestion:\n{question}\n\n'
    return user_prompt

def get_task_instruction_code(question, question_title=None, model_name=None):
    if model_name == 'qwq':
        user_prompt = f'Generate a correct Python program that passes all tests for the given problem. You should provide your final code within a Python code block using triple backticks (```python\nYOUR_CODE\n```).\n\nProblem Title: {question_title}\n\nProblem Statement:\n{question}\n\n'
    else:
        user_prompt = f'You will be given a question (problem specification) and will generate a correct Python program that matches the specification and passes all tests. You should think step by step to solve it.\n\nQuestion:\n{question}\n\nRead the inputs from stdin solve the problem and write the answer to stdout (do not directly test on the sample inputs). Enclose your code within delimiters as follows.\n\n```python\n# YOUR CODE HERE\n```\n\n'
    return user_prompt

def get_task_instruction_timeline(text, model_name=None):
    format_template = '- [DATE/TIME]: Event description\n\n'
    base_prompt = f'Text:\n{text}\n\n'
    if model_name == 'qwq':
        return f'Now it is March 14, 2025. Please create a comprehensive timeline based on the given text.Format each event as:\n{format_template}Ensure events are ordered chronologically and include specific dates/times when available.\n\n{base_prompt}'
    else:
        return f'Please summarize the key events from the text in chronological order. For each event, include the date/time (if available) and a clear description.\n\nFormat your timeline as:\n{format_template}{base_prompt}'
